<script setup lang="ts">
import{computed,onUnmounted,ref,watch}from'vue';
import{NAlert,NButton,NEmpty,NList,NListItem,NRadioButton,NRadioGroup,NSpace,NSpin,NTag}from'naive-ui';
import{api,ApiError,errorMessage,type Entity,type Workspace}from'../../shared/api';
import PageHeader from '../../shared/ui/PageHeader.vue';
interface RequestRow{requestId:string;workItemId:string|null;title:string;proposerEmployeeId:string;recipientKey:string;recipientLabel:string;status:string;safe:boolean;notificationStatus:string;notificationError?:string;updatedAt?:number;canRetryNotification?:boolean;canOpenConversation:boolean;conversationId?:string}
const props=defineProps<{workspace:Workspace;entities:Entity[]}>(),emit=defineEmits<{sessionExpired:[];openConversation:[entity:Entity,id:string];openWorkItem:[id:string]}>();
const retrying=ref('');let retryController=new AbortController();
const blockedReason=(r:RequestRow)=>r.notificationError==='human_recipient_use_forbidden'?'没有具备员工使用权的有效确认人，请检查使用范围与确认人配置。':r.notificationError==='human_recipient_ambiguous'?'无法选择有效确认人，且没有可用的默认确认人。':r.notificationError==='human_recipient_not_configured'?'尚未配置确认人。':r.notificationStatus==='unknown'?'送达或选择结果待核对，请勿重复发送。':'确认请求受阻，请检查确认人与渠道配置。';
const rows=ref<RequestRow[]>([]),busy=ref(false),error=ref(''),mode=ref<'recipient'|'employee'>('recipient'),selected=ref('all');let generation=0,controller=new AbortController();
const employeeName=(id:string)=>props.entities.find(e=>e.id===id)?.name??'数字员工';
const people=computed(()=>[...new Map(rows.value.map(r=>mode.value==='recipient'?[r.recipientKey,r.recipientLabel]:[r.proposerEmployeeId,employeeName(r.proposerEmployeeId)])).entries()].map(([id,label])=>({id,label})));
const filtered=computed(()=>rows.value.filter(r=>selected.value==='all'||(mode.value==='recipient'?r.recipientKey:r.proposerEmployeeId)===selected.value));watch(mode,()=>selected.value='all');
async function load(){const id=props.workspace.id,version=++generation;controller.abort();controller=new AbortController();busy.value=true;error.value='';try{const result=await api<{items:RequestRow[]}>(`/workspaces/${encodeURIComponent(id)}/work-items/pending-human`,controller.signal);if(version===generation&&id===props.workspace.id)rows.value=result.items;}catch(e){if(version===generation&&!controller.signal.aborted){error.value=errorMessage(e);if(e instanceof ApiError&&e.status===401)emit('sessionExpired');}}finally{if(version===generation)busy.value=false;}}
async function retry(r:RequestRow){if(retrying.value)return;const workspaceId=props.workspace.id;retrying.value=r.requestId;error.value='';retryController.abort();retryController=new AbortController();const signal=retryController.signal;try{await api(`/workspaces/${encodeURIComponent(workspaceId)}/work-items/pending-human/${encodeURIComponent(r.requestId)}/retry`,signal,{expectedUpdatedAt:r.updatedAt,expectedNotificationStatus:r.notificationStatus},'POST');if(workspaceId===props.workspace.id&&!signal.aborted)await load();}catch(e){if(workspaceId===props.workspace.id&&!signal.aborted){error.value=errorMessage(e);if(e instanceof ApiError&&e.status===401)emit('sessionExpired');}}finally{if(!signal.aborted)retrying.value='';}}
function open(r:RequestRow){const entity=props.entities.find(e=>e.id===r.proposerEmployeeId);if(r.canOpenConversation&&r.conversationId&&entity)emit('openConversation',entity,r.conversationId);}
watch(()=>props.workspace.id,()=>{retryController.abort();retrying.value='';rows.value=[];selected.value='all';void load();},{immediate:true});const timer=setInterval(()=>{if(!busy.value)void load();},5000);onUnmounted(()=>{generation++;controller.abort();retryController.abort();clearInterval(timer);});
</script>
<template><section class="human-requests"><PageHeader title="待人工确认"><NButton :loading="busy" @click="load">刷新</NButton></PageHeader><NAlert v-if="error" type="error" role="alert">{{error}}<span class="alert-retry"><NButton @click="load">重试</NButton></span></NAlert><NRadioGroup v-model:value="mode" aria-label="待确认分组"><NRadioButton value="recipient">按确认人</NRadioButton><NRadioButton value="employee">按提出员工</NRadioButton></NRadioGroup><nav class="people-filter" aria-label="确认人员筛选"><NButton :type="selected==='all'?'primary':'default'" @click="selected='all'">全部</NButton><NButton v-for="person in people" :key="person.id" :type="selected===person.id?'primary':'default'" @click="selected=person.id">{{person.label}}</NButton></nav><NSpin :show="busy"><NEmpty v-if="!filtered.length&&!error" :description="rows.length?'此筛选下没有待确认问题':'暂无待人工确认的问题'"/><NList v-else bordered><NListItem v-for="r in filtered" :key="r.requestId"><div class="request-row"><div class="request-copy"><strong>{{r.title}}</strong><p>{{employeeName(r.proposerEmployeeId)}} · {{r.recipientLabel}}</p><NSpace><NTag size="small">{{r.status==='confirmed'?'已确认，等待继续':'等待确认'}}</NTag><NTag v-if="['failed','blocked'].includes(r.notificationStatus)" type="error" size="small">确认请求受阻</NTag></NSpace><p v-if="['failed','blocked','unknown'].includes(r.notificationStatus)" role="status">{{blockedReason(r)}}</p></div><NSpace><NButton v-if="r.canRetryNotification" :disabled="!!retrying" :loading="retrying===r.requestId" @click="retry(r)">重新选择确认人</NButton><NButton v-if="r.canOpenConversation" @click="open(r)">前往私聊确认</NButton><NButton v-if="r.workItemId" @click="emit('openWorkItem',r.workItemId)">查看事项</NButton></NSpace></div></NListItem></NList></NSpin></section></template>
<style scoped>.human-requests{min-width:0}.people-filter{display:flex;gap:.5rem;overflow:auto;max-width:100%;padding:1rem 0}.request-row{display:flex;justify-content:space-between;align-items:center;gap:1rem;width:100%}.request-copy{min-width:0;overflow-wrap:anywhere}.request-copy p{color:var(--id-text-secondary);margin:.4rem 0}.human-requests :deep(.n-alert){margin-bottom:1rem}@media(max-width:600px){.request-row{align-items:flex-start;flex-direction:column}}</style>
